// Do not edit this file as it will be overwritten if HAMR codegen is rerun

use crate::bridge::consumer_consumer_api::*;
use crate::bridge::consumer_consumer_GUMBOX as GUMBOX;
use data::*;
use super::consumer_consumer_app::consumer_consumer;
use vstd::prelude::*;

verus! {

  impl consumer_consumer {
    #[verifier::external_body]
    pub fn pre_timeTriggered<API: consumer_consumer_Full_Api> (
      &mut self,
      api: &consumer_consumer_Application_Api<API>)
    {
      let sample = api.peek_sample();

      r2u2_core::load_bool_signal(&mut self.r2u2_monitor, 0, sample.is_some()); // Loading signal api_sample_nonEmpty into index 0
    }

    #[verifier::external_body]
    pub fn post_timeTriggered<API: consumer_consumer_Full_Api> (
      &mut self,
      api: &mut consumer_consumer_Application_Api<API>)
    {
      r2u2_core::monitor_step(&mut self.r2u2_monitor);
      let r2u2_time_stamp = self.r2u2_monitor.time_stamp;
      // Expire cached verdicts before applying this step's new outputs.
      for verdict in self.r2u2_monitor.verdict_cache.iter_mut() {
          if verdict.is_some() && r2u2_time_stamp > verdict.unwrap().time {
              *verdict = None;
          }
      }
      // Cache the newest verdict returned for each specification.
      let output_buffer = r2u2_core::get_output_buffer(&self.r2u2_monitor.inner);
      let verdict_cache = &mut self.r2u2_monitor.verdict_cache;
      for out in output_buffer {
          verdict_cache[out.spec_num as usize] = Some(out.verdict);
      }
      // Send the latest cached verdict through each mapped alert port.
      if let Some(verdict) = self.r2u2_monitor.verdict_cache[0] {
          if !verdict.truth {
              api.put_sample_alert();
          }
      }
    }
  }

  #[verifier::external_body]
  pub struct R2U2Monitor {
    inner: r2u2_core::Monitor,
    // Cache latest verdict (if applicable) per C2PO specification between monitor steps.
    verdict_cache: [Option<r2u2_core::r2u2_verdict>; 1],
  }

  #[verifier::external]
  impl core::ops::Deref for R2U2Monitor {
    type Target = r2u2_core::Monitor;
    fn deref(&self) -> &Self::Target { &self.inner }
  }

  #[verifier::external]
  impl core::ops::DerefMut for R2U2Monitor {
    fn deref_mut(&mut self) -> &mut Self::Target { &mut self.inner }
  }

  #[verifier::external_body]
  pub(super) fn default_r2u2_monitor() -> R2U2Monitor {
    R2U2Monitor {
      inner: r2u2_core::Monitor::default(),
      verdict_cache: [None; 1],
    }
  }

  #[verifier::external_body]
  pub(super) fn load_spec(monitor: &mut R2U2Monitor) {
    r2u2_core::update_binary_file(include_bytes!("spec.bin"), monitor);
  }

}
